\title{The Domination--Packing Ratio:\\ Local Cover Engines, Geometric Bounds, and Extremal Families}
\author{Aristotle}
\date{August 20, 2026}

\begin{document}
\maketitle

\begin{abstract}
For a finite simple graph $G$, the \emph{domination number} $\gamma(G)$ is the least size of a vertex set meeting every radius-$1$ ball (closed neighbourhood) of $G$, and the \emph{packing number} $\rho(G)$ is the largest number of pairwise disjoint radius-$1$ balls. Equivalently, $\gamma$ and $\rho$ are the transversal and matching numbers of the hypergraph of radius-$1$ balls, and $\rho(G)\le\gamma(G)$ always. We develop a self-contained theory of the reverse, Erd\H{o}s--P\'osa-type inequality $\gamma \le c\,\rho$.

Our central tool is a \emph{local cover principle}: if every radius-$2$ neighbourhood of $G$ can be dominated by at most $c$ vertices, then $\gamma(G)\le c\,\rho(G)$, because a maximum packing is maximal and hence its radius-$2$ neighbourhoods cover the graph. From it we derive $\gamma \le (\Delta+1)\rho$ for every finite graph of maximum degree $\Delta$, and a metric form: if $G$ is represented by points of a metric space $X$ with adjacency ``distinct and at distance $\le 1$'', and no ball of radius $2$ in $X$ contains more than $N$ points pairwise more than $1$ apart, then $\gamma \le N\rho$. A volume comparison gives the local packing bound $25$ for the plane and $5^n$ for $\mathbb{R}^n$, hence $\gamma \le 25\rho$ for unit disk graphs and $\gamma \le 5^n\rho$ for unit ball graphs in $\mathbb{R}^n$.

In dimension one the local packing bound is exactly $4$ (and not $3$), so the metric method yields $\gamma\le 4\rho$ for unit interval graphs and no better. The truth is sharper: we isolate an abstract \emph{greedy dominator criterion} and prove that it alone forces $\gamma(G)=\rho(G)$. Interval graphs satisfy it via an earliest-endpoint sweep, and forests satisfy it via a deepest-vertex/parent rule, recovering the classical theorem of Meir and Moon. The criterion is a genuine restriction: the $4$-cycle, a unit disk graph with $\gamma=2$ and $\rho=1$, fails it.

On the lower-bound side, the Wagner graph $V_8$ has $\rho=1$ and $\gamma=3$, and $k$ disjoint copies of it have $\rho=k$ and $\gamma=3k$, so the ratio $3$ persists for arbitrarily large packing number and no bound $\gamma\le c\rho+b$ holds with $c<3$. Finally, over all finite graphs the ratio is unbounded: a spread graph built from a clique of $k$ indices together with all $t$-subsets, $k<2t$, has $\rho=1$ and $\gamma \ge k-t+1$.
\end{abstract}

\section{Introduction}

Fix a finite simple graph $G=(V,E)$ and, for $v\in V$, write
\[
B(v) := \{v\}\cup\{u\in V : uv\in E\}
\]
for the closed neighbourhood of $v$, the \emph{radius-$1$ ball} at $v$. Consider the hypergraph $\mathcal{B}(G)=\{B(v):v\in V\}$ on $V$. A \emph{dominating set} is a transversal of $\mathcal{B}(G)$ and $\gamma(G)$ is its minimum size; a \emph{packing} is a matching of $\mathcal{B}(G)$ and $\rho(G)$ is its maximum size. This paper studies
\[
\sup_{G\in\mathcal{C}}\frac{\gamma(G)}{\rho(G)}
\]
over graph classes $\mathcal{C}$, with attention to the geometric classes: unit disk graphs, unit ball graphs in $\mathbb{R}^n$, and interval graphs. Throughout, all graphs are finite and simple.

\section{Definitions and the trivial duality}

\begin{definition}[Ball, packing, packing number]
For $v\in V$, $B(v)=\{u : u=v \text{ or } uv\in E\}$. A finite $P\subseteq V$ is a \emph{packing} if $B(p)\cap B(q)=\emptyset$ for all distinct $p,q\in P$, and $\rho(G)=\max\{|P| : P \text{ a packing}\}$.
\end{definition}

\begin{definition}[Dominating set, domination number]
$D\subseteq V$ is \emph{dominating} if every $v\in V$ lies in $D$ or is adjacent to some $d\in D$, and $\gamma(G)=\min\{|D| : D \text{ dominating}\}$.
\end{definition}

\begin{lemma}[Balls meet iff distance $\le 2$]\label{lem:meet}
For $u,v\in V$ we have $B(u)\cap B(v)\ne\emptyset$ if and only if $\dist(u,v)\le 2$.
\end{lemma}

\begin{proof}
If $w\in B(u)\cap B(v)$ then each of $w=u$ / $w\sim u$ and $w=v$ / $w\sim v$ holds, giving distance $0$, $1$, $1$ or $2$. Conversely, if $u=v$ take $w=u$; if $u\sim v$ take $w=v$; if $u\sim w\sim v$ take $w$.
\end{proof}

\begin{corollary}
$P$ is a packing if and only if its elements are pairwise at distance at least $3$.
\end{corollary}

\begin{theorem}[Trivial duality]\label{thm:trivial}
For every finite graph $G$, $\rho(G)\le\gamma(G)$.
\end{theorem}

\begin{proof}
Let $P$ be a maximum packing and $D$ a minimum dominating set. For $p\in P$ choose $f(p)\in D\cap B(p)$: either $p\in D$, or some $d\in D$ is adjacent to $p$, and then $d\in B(p)$. The balls $B(p)$ are pairwise disjoint, so $f$ is injective and $|P|\le|D|$.
\end{proof}

\section{The local cover principle}

\begin{lemma}[Maximum packings are maximal]\label{lem:maximal}
If $P$ is a packing with $|P|=\rho(G)$, then every $v\in V$ satisfies $\dist(v,p)\le 2$ for some $p\in P$.
\end{lemma}

\begin{proof}
Otherwise $B(v)$ is disjoint from all $B(p)$, so $v\notin P$ and $P\cup\{v\}$ is a larger packing.
\end{proof}

\begin{theorem}[Local cover principle]\label{thm:engine}
Let $c\in\mathbb{N}$ and suppose that for every $p\in V$ there is $D_p\subseteq V$ with $|D_p|\le c$ dominating every $u$ with $\dist(u,p)\le 2$. Then $\gamma(G)\le c\,\rho(G)$.
\end{theorem}

\begin{proof}
Take a packing $P$ with $|P|=\rho(G)$ and set $D:=\bigcup_{p\in P}D_p$. Given $v$, Lemma~\ref{lem:maximal} supplies $p\in P$ with $\dist(v,p)\le 2$, so $v$ is dominated by $D_p\subseteq D$. Finally $|D|\le\sum_{p\in P}|D_p|\le c|P|=c\,\rho(G)$.
\end{proof}

\begin{corollary}[Degree bound]\label{cor:degree}
For every finite graph of maximum degree $\Delta$, $\gamma(G)\le(\Delta+1)\rho(G)$.
\end{corollary}

\begin{proof}
Take $D_p:=B(p)$, of size at most $\Delta+1$. If $\dist(u,p)\le 2$, Lemma~\ref{lem:meet} gives $w\in B(u)\cap B(p)$; then $w\in D_p$ and $u\in B(w)$.
\end{proof}

\section{The metric form and Euclidean bounds}

\begin{definition}[Unit distance representation]
A \emph{metric representation} of $G$ in a metric space $X$ is a map $\pos:V\to X$ with $uv\in E \iff u\ne v$ and $d(\pos u,\pos v)\le 1$. A \emph{unit disk graph} has a representation in $\mathbb{R}^2$, a \emph{unit ball graph in $\mathbb{R}^n$} one in $\mathbb{R}^n$, a \emph{unit interval graph} one in $\mathbb{R}$.
\end{definition}

\begin{definition}[Local packing bound]
$X$ has \emph{local packing bound} $N$ if for every $c\in X$ and every finite $T\subseteq X$ with $d(x,c)\le 2$ for all $x\in T$ and $d(x,y)>1$ for all distinct $x,y\in T$, one has $|T|\le N$.
\end{definition}

\begin{lemma}[Maximal independent subsets dominate]\label{lem:mis}
For every finite $T\subseteq V$ there is $I\subseteq T$ independent in $G$ that dominates $T$.
\end{lemma}

\begin{proof}
Take $I\subseteq T$ independent of maximum size; a vertex of $T$ neither in $I$ nor adjacent to $I$ could be added.
\end{proof}

\begin{theorem}[Local cover from a local packing bound]\label{thm:localcover}
If $G$ has a metric representation in $X$ and $X$ has local packing bound $N$, then for every $p\in V$ there is $D_p$ with $|D_p|\le N$ dominating $\{u:\dist_G(u,p)\le 2\}$.
\end{theorem}

\begin{proof}
Let $T=\{u : \dist_G(u,p)\le 2\}$ and $I\subseteq T$ a maximal independent subset (Lemma~\ref{lem:mis}). For $u\in T$ pick $w\in B(u)\cap B(p)$ (Lemma~\ref{lem:meet}); then $d(\pos u,\pos w)\le 1$ and $d(\pos w,\pos p)\le 1$, so $d(\pos u,\pos p)\le 2$. Distinct elements of $I$ are non-adjacent, hence more than $1$ apart, so $\pos$ is injective on $I$ and the local packing bound gives $|I|\le N$.
\end{proof}

\begin{theorem}[Metric Erd\H{o}s--P\'osa bound]\label{thm:metric}
If $G$ has a metric representation in a metric space with local packing bound $N$, then $\gamma(G)\le N\rho(G)$.
\end{theorem}

\begin{proof}
Combine Theorems~\ref{thm:localcover} and \ref{thm:engine}.
\end{proof}

\begin{proposition}[Volume comparison]\label{prop:volume}
Let $X$ be an $n$-dimensional normed space with Haar measure $\mu$, let $c\in X$, $r,\delta>0$, and let $T$ be finite with $d(x,c)\le r$ for $x\in T$ and $d(x,y)>\delta$ for distinct $x,y\in T$. Then $|T|\le\big((2r+\delta)/\delta\big)^n$.
\end{proposition}

\begin{proof}
The balls $B(x,\delta/2)$, $x\in T$, are pairwise disjoint and contained in $B(c,r+\delta/2)$; comparing measures and using $\mu(B(0,s))=s^n\mu(B(0,1))$ gives the bound.
\end{proof}

\begin{corollary}\label{cor:euclid}
The plane has local packing bound $25$ and $\mathbb{R}^n$ has local packing bound $5^n$ (take $r=2$, $\delta=1$).
\end{corollary}

\begin{theorem}[Unit disk graphs]\label{thm:udg}
For every unit disk graph $G$, $\gamma(G)\le 25\,\rho(G)$; for every unit ball graph in $\mathbb{R}^n$, $\gamma(G)\le 5^n\rho(G)$.
\end{theorem}

\begin{corollary}[Erd\H{o}s--P\'osa form]
For every unit disk graph $G$ and every $k$: either $G$ contains $k$ pairwise disjoint radius-$1$ balls, or at most $25(k-1)$ vertices meet all radius-$1$ balls.
\end{corollary}

\begin{remark}
The constant $25$ is not optimal: the literature gives $\gamma\le 5\rho$ for planar graphs and $\gamma\le (18\sqrt3/\pi)\rho\approx 9.924\rho$ for unit disk graphs by finer arguments. Theorem~\ref{thm:udg} obtains a bound of the correct shape from a single elementary volume count.
\end{remark}

\section{Dimension one}

\begin{theorem}[The line has local packing bound $4$]\label{thm:line4}
If $T\subseteq\mathbb{R}$ is finite, contained in $[c-2,c+2]$, and pairwise more than $1$ apart, then $|T|\le 4$.
\end{theorem}

\begin{proof}
The map $f(x)=\min\big(\lfloor x-(c-2)\rfloor,3\big)$ takes values in $\{0,1,2,3\}$ and is injective on such a set: consecutive elements differ by more than $1$, so their floors increase, and at most one element can be clipped at $3$ since the clipped range $[c+1,c+2]$ has length $1$.
\end{proof}

\begin{proposition}[Optimality of $4$]\label{prop:not3}
The line does not have local packing bound $3$: the points $0,\tfrac{11}{10},\tfrac{11}{5},\tfrac{33}{10}$ lie within distance $2$ of $2$ and are pairwise more than $1$ apart.
\end{proposition}

\begin{corollary}
For every unit interval graph, $\gamma\le 4\rho$, and this is the best bound obtainable from the metric method.
\end{corollary}

\begin{definition}[Interval representation]
An \emph{interval representation} of $G$ assigns to each $v$ a nonempty closed interval $[\ell(v),r(v)]$, distinct vertices being adjacent exactly when their intervals meet, i.e.\ $\ell(u)\le r(v)$ and $\ell(v)\le r(u)$.
\end{definition}

\begin{lemma}\label{lem:intball}
In an interval representation, $w\in B(u)$ iff $\ell(w)\le r(u)$ and $\ell(u)\le r(w)$.
\end{lemma}

\begin{theorem}[Interval greedy]\label{thm:intgreedy}
Let $G$ have an interval representation. For every finite $S\subseteq V$ there are a packing $P\subseteq S$ and a set $D$ with $|D|\le|P|$ dominating $S$.
\end{theorem}

\begin{proof}
Induct on $|S|$. For $S\ne\emptyset$ let $u\in S$ minimize $r(u)$, let $d\in B(u)$ maximize $r(d)$, and set $S':=\{s\in S : s\notin B(d)\}$, a proper subset since $u\in B(d)$. Let $P',D'$ be obtained for $S'$ and set $P:=\{u\}\cup P'$, $D:=\{d\}\cup D'$. Then $D$ dominates $S$, and $|D|\le|P|$ since $u\notin P'\subseteq S'$. For the packing property, let $q\in P'$; as $q\notin B(d)$, Lemma~\ref{lem:intball} gives $\ell(q)>r(d)$ or $\ell(d)>r(q)$, and the latter is impossible because $\ell(d)\le r(u)\le r(q)$. Hence $\ell(q)>r(d)\ge r(x)$ for all $x\in B(u)$, so no element of $B(u)$ meets $q$'s interval and $B(u)\cap B(q)=\emptyset$.
\end{proof}

\begin{theorem}[Interval graphs]\label{thm:interval}
For every finite interval graph $G$, $\gamma(G)=\rho(G)$.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:intgreedy} with $S=V$ to get $\gamma\le|D|\le|P|\le\rho$, and combine with Theorem~\ref{thm:trivial}.
\end{proof}

\begin{corollary}
For every unit interval graph $G$, $\gamma(G)=\rho(G)$: set $\ell(v)=\pos(v)-\tfrac12$, $r(v)=\pos(v)+\tfrac12$.
\end{corollary}

\begin{example}[Paths]
For the path $P_n$, $\gamma(P_n)=\rho(P_n)=\lceil n/3\rceil=\lfloor (n+2)/3\rfloor$: place vertex $i$ at $i\in\mathbb{R}$ and note that the vertices with index divisible by $3$ form a packing, their balls $\{i-1,i,i+1\}$ being pairwise disjoint.
\end{example}

\section{An abstract greedy criterion and the Meir--Moon theorem}

\begin{definition}[Greedy cover, greedy dominator]
$G$ \emph{has a greedy cover with constant $c$} if for every nonempty finite $S\subseteq V$ there are $u\in S$ and $D$ with $|D|\le c$ dominating every $s\in S$ with $B(u)\cap B(s)\ne\emptyset$. It \emph{has a greedy dominator} if for every nonempty finite $S$ there are $u\in S$ and a single vertex $d$ such that every such $s$ lies in $B(d)$.
\end{definition}

\begin{theorem}[Greedy engine]\label{thm:greedyengine}
If $G$ has a greedy cover with constant $c$, then every finite $S\subseteq V$ admits a packing $P\subseteq S$ and a set $D$ with $|D|\le c|P|$ dominating $S$; consequently $\gamma(G)\le c\,\rho(G)$.
\end{theorem}

\begin{proof}
Induct on $|S|$. Take $u\in S$ and $D_u$ as in the definition, let $S'$ be the vertices of $S$ not dominated by $D_u$ (a proper subset, since $u$ is dominated), and recurse. Set $P:=\{u\}\cup P'$ and $D:=D_u\cup D'$: $D$ dominates $S$, $|D|\le c|P|$, and for $q\in P'\subseteq S'$ the vertex $q$ is undominated by $D_u$, so $B(u)\cap B(q)=\emptyset$ by the defining property of $u$.
\end{proof}

\begin{theorem}[Collapse theorem]\label{thm:collapse}
If $G$ has a greedy dominator, then $\gamma(G)=\rho(G)$.
\end{theorem}

\begin{proof}
A greedy dominator is a greedy cover with $c=1$ (take $D=\{d\}$). Apply Theorems~\ref{thm:greedyengine} and \ref{thm:trivial}.
\end{proof}

\begin{theorem}
Every interval graph has a greedy dominator.
\end{theorem}

\begin{proof}
Given $S$, take $u\in S$ minimizing $r(u)$ and $d\in B(u)$ maximizing $r(d)$. If $w\in B(u)\cap B(s)$ then $r(w)\le r(d)$, so $\ell(s)\le r(w)\le r(d)$; also $\ell(d)\le r(u)\le r(s)$. Lemma~\ref{lem:intball} gives $s\in B(d)$.
\end{proof}

\begin{theorem}[Forests have a greedy dominator]\label{thm:forest}
Every finite forest has a greedy dominator.
\end{theorem}

\begin{proof}
Pick $r\in S$, let $C$ be the vertices of $S$ reachable from $r$, and let $u\in C$ maximize the depth $\dist(r,u)$; let $d$ be the parent of $u$ (a neighbour at depth $\dist(r,u)-1$), or $u$ itself if $u=r$. Two facts about acyclic graphs are used: adjacent vertices have different depths, and each vertex has at most one parent (in each case a cycle would otherwise be created from two geodesics plus the connecting edges).

Let $s\in S$ with $B(u)\cap B(s)\ne\emptyset$. Then $s$ lies in the component of $r$, hence $s\in C$ and $\dist(r,s)\le\dist(r,u)$. If $s=u$ then $s\in B(d)$. If $s\sim u$, then $s$ has depth $\dist(r,u)-1$ (depth $+1$ is excluded by maximality), so $s$ is a parent of $u$ and $s=d$. If $\dist(u,s)=2$, take a common neighbour $z$; either $z=d$ and $s\in B(d)$, or $z$ is a child of $u$, in which case $s$, adjacent to $z$ and of depth at most $\dist(r,u)$, is a parent of $z$ and hence equals $u$, so again $s\in B(d)$.
\end{proof}

\begin{theorem}[Meir--Moon]\label{thm:meirmoon}
For every finite forest $F$, $\gamma(F)=\rho(F)$; in particular $\gamma(T)=\rho(T)$ for every finite tree.
\end{theorem}

\begin{proposition}
The $4$-cycle has no greedy dominator: $\rho(C_4)=1$ while $\gamma(C_4)=2$. Consequently $C_4$ is not a forest.
\end{proposition}

\begin{corollary}
$\sup\gamma/\rho \ge 2$ over unit disk graphs: place the vertices of $C_4$ at $(0,0)$, $(\tfrac45,0)$, $(\tfrac45,\tfrac{21}{25})$, $(0,\tfrac{21}{25})$, whose sides have length $\le 1$ and whose diagonals have length $\tfrac{29}{25}>1$.
\end{corollary}

\section{Extremal families}

\subsection{The Wagner graph and the persistence of the ratio $3$}

\begin{definition}
The \emph{Wagner graph} $V_8$ (M\"obius ladder $M_4$) has vertex set $\mathbb{Z}/8$ with $i\sim i+1$ and $i\sim i+4$; it is $3$-regular on $8$ vertices.
\end{definition}

\begin{proposition}\label{prop:wagner}
$\rho(V_8)=1$ and $\gamma(V_8)=3$.
\end{proposition}

\begin{proof}
Each ball is $B(i)=\{i-1,i,i+1,i+4\}$, of size $4$; a finite check shows any two of these intersect, so $\rho=1$. The set $\{0,1,2\}$ dominates, and no two vertices do, since $|B(i)\cup B(j)|=8$ would require $B(i)$ and $B(j)$ to be disjoint.
\end{proof}

\begin{definition}
$W_k$ denotes $k$ disjoint copies of $V_8$: vertex set $\{1,\dots,k\}\times\mathbb{Z}/8$ with $(i,a)\sim(j,b)$ iff $i=j$ and $a\sim b$ in $V_8$.
\end{definition}

\begin{theorem}\label{thm:wk}
$\rho(W_k)=k$ and $\gamma(W_k)=3k$; in particular $\gamma(W_k)=3\rho(W_k)$ with $\rho$ arbitrarily large.
\end{theorem}

\begin{proof}
Every ball stays inside its copy. A packing meets each copy at most once (all balls within a copy intersect, by Proposition~\ref{prop:wagner}), and $\{(i,0)\}_i$ shows $k$ is attained. For domination, $\{1,\dots,k\}\times\{0,1,2\}$ dominates; conversely, for a dominating set $D$ with fibres $D_i$, the projection of $D_i$ dominates $V_8$, so $|D_i|\ge 3$ and $|D|=\sum_i|D_i|\ge 3k$.
\end{proof}

\begin{corollary}[No constant below $3$]
If $\gamma(G)\le c\rho(G)+b$ holds for all $G$ in a class containing every $W_k$, then $c\ge 3$: otherwise $3k\le ck+b$ fails at $k=b+1$.
\end{corollary}

\subsection{Spread graphs: unbounded ratio in general}

\begin{definition}
For $k,t\in\mathbb{N}$, the \emph{spread graph} $S_{k,t}$ has vertex set $[k]\sqcup\binom{[k]}{t}$: the indices form a clique, the $t$-subsets an independent set, and $i\sim S$ iff $i\in S$.
\end{definition}

\begin{theorem}
If $0<k$, $0<t$ and $k<2t$, then $\rho(S_{k,t})=1$.
\end{theorem}

\begin{proof}
Any two $t$-subsets meet, since $|S\cap T|\ge 2t-k>0$. Hence all balls pairwise intersect: two index-balls share an index; $B(i)$ and $B(S)$ share any element of $S$; $B(S)$ and $B(T)$ share an element of $S\cap T$.
\end{proof}

\begin{theorem}
If $0<t\le k$ then $\gamma(S_{k,t})\ge k-t+1$.
\end{theorem}

\begin{proof}
Let $D$ be dominating, $A$ its indices, $F$ its subsets. If $|A|\ge k-t+1$ we are done; otherwise $|A^c|\ge t$, and fixing a $(t-1)$-subset $E\subseteq A^c$, every $t$-set $E\cup\{x\}$ with $x\in A^c\setminus E$ is disjoint from $A$, hence has no neighbour in $D$ and must itself lie in $D$. This gives $|F|\ge k-|A|-t+1$ and $|D|\ge|A|+|F|\ge k-t+1$.
\end{proof}

\begin{theorem}[Unboundedness]
For every $m\ge 1$, $S_{2m,m+1}$ has $\rho=1$ and $\gamma\ge m$. Hence $\sup\gamma/\rho=\infty$ over all finite graphs, and no bound $\gamma\le c\rho+b$ holds in general.
\end{theorem}

\section{Algorithms}

\textbf{Algorithm A (maximal packing / local cover).} Greedily build a maximal packing $P$ (add $v$ whenever $\dist(v,p)\ge 3$ for all chosen $p$), then for each $p\in P$ compute a maximal independent subset $I_p$ of the radius-$2$ neighbourhood of $p$ and output $D=\bigcup_p I_p$. Correctness follows from Lemmas~\ref{lem:maximal} and \ref{lem:mis}, and for geometric inputs $|D|\le N\rho(G)$ by Theorem~\ref{thm:localcover}. The algorithm returns both an approximate dominating set and a packing certifying a lower bound.

\textbf{Algorithm B (interval sweep).} Sort by right endpoint; repeatedly take the first undominated $u$, output the vertex $d$ meeting $u$ with the largest right endpoint, bank $u$ in $P$, delete $B(d)$. Yields $|D|=|P|$, hence simultaneously optimal domination and packing in $O(n\log n)$.

\textbf{Algorithm C (forest sweep).} Root each component; repeatedly take the deepest undominated $u$, output its parent, bank $u$, delete the parent's ball. Yields $|D|=|P|$ in $O(n)$ after a BFS.

All three follow the schema: bank a packing centre, spend the dominators covering its radius-$2$ neighbourhood, recurse.

\section{Discussion and future directions}

\begin{center}
\begin{tabular}{ll}
\toprule
class & ratio $\gamma/\rho$ \\
\midrule
all finite graphs & unbounded \\
maximum degree $\Delta$ & $\le \Delta+1$ \\
forests, trees & $=1$ \\
interval and unit interval graphs, paths & $=1$ \\
unit interval graphs, metric method alone & $\le 4$, optimal for that method \\
unit disk graphs & $\ge 2$; $\le 25$ \\
unit ball graphs in $\mathbb{R}^n$ & $\le 5^n$ \\
classes containing all Wagner unions & $\ge 3$ \\
\bottomrule
\end{tabular}
\end{center}

The entire geometric input is one finite number: the maximum size of a $1$-separated set in a ball of radius $2$. In dimension one the two methods separate cleanly, the metric method saturating at $4$ while the greedy criterion delivers the exact answer $1$.

\begin{conjecture}[Optimal planar local packing bound]
A closed disk of radius $2$ in the plane contains at most $19$ points that are pairwise more than $1$ apart, and $19$ is attained (for instance by the centre, a ring of six points at radius $1.05$, and a ring of twelve points at radius $2$ offset by $15^\circ$, whose minimum mutual distance is about $1.023$); consequently the plane has local packing bound $19$ and $\gamma\le 19\rho$ for unit disk graphs, while no bound below $19$ follows from the maximal-independent-set argument.
\end{conjecture}

Further directions: (i) reproduce the published constants $5$ (planar, via discharging or structural decomposition) and $18\sqrt3/\pi$ (unit disk, via hexagonal density), and determine the optimal constants, which remain open with a best known lower bound of $3$; (ii) characterize the graphs possessing a greedy dominator, and the quantitative version with constant $c$; (iii) determine the true exponential rate of the local packing bound of $\mathbb{R}^n$, and extend to $\ell_p$ and doubling metric spaces, where the local packing bound is a doubling constant; (iv) analyse the worst case of Algorithm A itself, as opposed to the worst case of the ratio.

\section{Conclusion}

Without hypotheses the gap between domination and packing is unbounded; with bounded degree it is at most $\Delta+1$; with one-dimensional or acyclic structure it vanishes; and with a Euclidean embedding it is bounded by a purely geometric constant. On the lower-bound side, the ratio $3$ realized by the Wagner graph survives disjoint unions and therefore persists at every scale, so no Erd\H{o}s--P\'osa inequality with constant below $3$ is available even with additive slack. What separates the classes is the presence of a greedy dominator: a local rule letting one vertex pay for the whole radius-$2$ neighbourhood of the next packing centre.

\end{document}

