"""How good is the local-cover construction in practice?

The local cover principle turns a maximal packing into a dominating set:
every vertex lies within distance 2 of some packing centre, and a maximal
independent subset of a radius-2 neighbourhood dominates it.  In the plane
a radius-2 ball holds at most 25 points that are pairwise more than 1 apart,
which is where the guarantee gamma <= 25*rho comes from.

This demo measures, on random unit disk graphs, three quantities:
    rho(G)            (exact, exhaustive)
    gamma(G)          (exact, exhaustive)
    |D| from the local-cover construction,
so one can see the certified sandwich rho <= gamma <= |D| <= 25*rho and how
much slack the crude constant 25 actually leaves.
"""

from __future__ import annotations

import math
import random
import statistics
from collections import deque
from itertools import combinations
from typing import Dict, FrozenSet, Iterable, List, Sequence, Set, Tuple

Graph = Dict[int, Set[int]]


def unit_disk_graph(pts: Sequence[Tuple[float, float]]) -> Graph:
    g: Graph = {i: set() for i in range(len(pts))}
    for i, j in combinations(range(len(pts)), 2):
        if math.dist(pts[i], pts[j]) <= 1.0:
            g[i].add(j)
            g[j].add(i)
    return g


def ball(g: Graph, v: int) -> FrozenSet[int]:
    return frozenset({v} | g[v])


def within_two(g: Graph, p: int) -> Set[int]:
    seen, q = {p}, deque([(p, 0)])
    while q:
        x, d = q.popleft()
        if d == 2:
            continue
        for y in g[x]:
            if y not in seen:
                seen.add(y)
                q.append((y, d + 1))
    return seen


def local_cover(g: Graph) -> Tuple[List[int], List[int]]:
    packing: List[int] = []
    blocked: Set[int] = set()
    for v in sorted(g):
        if v not in blocked:
            packing.append(v)
            blocked |= within_two(g, v)
    dom: Set[int] = set()
    for p in packing:
        chosen: List[int] = []
        for v in sorted(within_two(g, p)):
            if all(v not in g[u] for u in chosen):
                chosen.append(v)
        dom |= set(chosen)
    return sorted(dom), packing


def exact_gamma(g: Graph) -> int:
    vs = list(g)
    for size in range(len(vs) + 1):
        for cand in combinations(vs, size):
            cov: Set[int] = set()
            for x in cand:
                cov |= ball(g, x)
            if cov == set(g):
                return size
    raise RuntimeError


def exact_rho(g: Graph) -> int:
    vs = list(g)
    for size in range(len(vs), -1, -1):
        for cand in combinations(vs, size):
            if all(not (ball(g, a) & ball(g, b)) for a, b in combinations(cand, 2)):
                return size
    raise RuntimeError


def main() -> None:
    rng = random.Random(31337)
    ratios: List[float] = []
    slacks: List[float] = []
    print(f"{'n':>3} {'rho':>4} {'gamma':>6} {'|D|':>4} {'|D|/gamma':>10} {'25*rho':>7}")
    for _ in range(25):
        n = rng.randint(6, 11)
        pts = [(rng.uniform(0, 3.0), rng.uniform(0, 3.0)) for _ in range(n)]
        g = unit_disk_graph(pts)
        dom, pack = local_cover(g)
        gam, rho = exact_gamma(g), exact_rho(g)
        assert rho <= gam <= len(dom) <= 25 * rho
        ratios.append(gam / rho)
        slacks.append(len(dom) / gam)
        print(f"{n:>3} {rho:>4} {gam:>6} {len(dom):>4} {len(dom)/gam:>10.2f} {25*rho:>7}")
    print()
    print(f"mean exact ratio gamma/rho    : {statistics.mean(ratios):.3f} "
          f"(max {max(ratios):.3f})")
    print(f"mean construction slack |D|/gamma: {statistics.mean(slacks):.3f} "
          f"(max {max(slacks):.3f})")
    print("the certified sandwich rho <= gamma <= |D| <= 25*rho held in every instance")


if __name__ == "__main__":
    main()

