"""Local-cover approximation for domination, with a packing certificate.

Given a finite graph G, the algorithm returns a dominating set D together
with a packing P such that |P| <= gamma(G) <= |D|.  For a graph represented
by points of a metric space whose radius-2 balls contain at most N pairwise
1-separated points (N = 25 in the plane, 5^n in R^n, 4 on the line), the
output satisfies |D| <= N * |P| <= N * gamma(G).
"""

from __future__ import annotations

from collections import deque
from itertools import combinations
from typing import Dict, FrozenSet, Iterable, List, Sequence, Set, Tuple

Vertex = int
Graph = Dict[Vertex, Set[Vertex]]


def ball(g: Graph, v: Vertex) -> FrozenSet[Vertex]:
    """Radius-1 ball (closed neighbourhood) of v."""
    return frozenset({v} | g[v])


def within_two(g: Graph, p: Vertex) -> Set[Vertex]:
    """All vertices at graph distance at most 2 from p (a BFS to depth 2)."""
    seen: Set[Vertex] = {p}
    frontier = deque([(p, 0)])
    while frontier:
        x, d = frontier.popleft()
        if d == 2:
            continue
        for y in g[x]:
            if y not in seen:
                seen.add(y)
                frontier.append((y, d + 1))
    return seen


def maximal_packing(g: Graph, order: Sequence[Vertex] | None = None) -> List[Vertex]:
    """Greedily build a maximal packing: add v whenever its ball misses all
    balls chosen so far (equivalently, dist(v, p) >= 3 for every chosen p)."""
    chosen: List[Vertex] = []
    blocked: Set[Vertex] = set()
    for v in (order if order is not None else sorted(g)):
        if v in blocked:
            continue
        chosen.append(v)
        blocked |= within_two(g, v)
    return chosen


def maximal_independent_subset(g: Graph, t: Iterable[Vertex]) -> List[Vertex]:
    """A maximal independent subset of t; being maximal, it dominates t."""
    chosen: List[Vertex] = []
    for v in t:
        if all(v not in g[u] for u in chosen):
            chosen.append(v)
    return chosen


def local_cover_dominating_set(g: Graph) -> Tuple[List[Vertex], List[Vertex]]:
    """Return (D, P): a dominating set and a packing certificate.

    Correctness.  A maximal packing P has the property that every vertex lies
    within distance 2 of some p in P (else p could be added).  A maximal
    independent subset of the radius-2 neighbourhood of p dominates that
    neighbourhood.  The union over p in P therefore dominates the graph.
    """
    packing = maximal_packing(g)
    dom: List[Vertex] = []
    for p in packing:
        dom.extend(maximal_independent_subset(g, sorted(within_two(g, p))))
    return sorted(set(dom)), packing


def is_dominating(g: Graph, d: Iterable[Vertex]) -> bool:
    covered: Set[Vertex] = set()
    for x in d:
        covered |= ball(g, x)
    return covered == set(g)


def is_packing(g: Graph, p: Sequence[Vertex]) -> bool:
    return all(not (ball(g, a) & ball(g, b)) for a, b in combinations(p, 2))


if __name__ == "__main__":
    # 5x5 grid graph: a planar (indeed unit disk) instance
    n = 5
    g: Graph = {i * n + j: set() for i in range(n) for j in range(n)}
    for i in range(n):
        for j in range(n):
            for di, dj in ((0, 1), (1, 0)):
                a, b = i + di, j + dj
                if a < n and b < n:
                    g[i * n + j].add(a * n + b)
                    g[a * n + b].add(i * n + j)
    dom, pack = local_cover_dominating_set(g)
    assert is_dominating(g, dom) and is_packing(g, pack)
    print(f"5x5 grid: |D| = {len(dom)}, packing certificate |P| = {len(pack)}")
    print(f"certified bounds: {len(pack)} <= gamma <= {len(dom)}")
    print("guarantee for planar/unit disk inputs: |D| <= 25*|P| =", 25 * len(pack))
